import { useState } from "react";

export default function ProductCard({
    p,
    cart,
    addToCart,
    increaseQty,
    decreaseQty,
}) {
    const [liked, setLiked] = useState(false);

    const id = p.id || p.Id;
    const name = p.name || p.Name;
    const brand = p.brand || p.Brand;
    const imageUrl = p.imageUrl || p.ImageUrl;

    const price =
        p.price ??
        p.Price ??
        p.minPrice ??
        p.MinPrice ??
        p.sellingPrice ??
        p.SellingPrice ??
        0;

    const discount = p.discount ?? p.DiscountPercentage ?? 0;
    const isHotDeal = p.isHotDeal ?? p.IsHotDeal ?? false;
    const dealEnd = p.dealEndDate ?? p.DealEndDate;

    const priceType = (p.priceType || p.PriceType || "")
        .toLowerCase()
        .trim();

    const isNormal = priceType === "normal";

    const isDealActive =
        isHotDeal &&
        discount > 0 &&
        dealEnd &&
        new Date(dealEnd) > new Date();

    const finalPrice = isDealActive
        ? price - (price * discount) / 100
        : price;

    return (
        <div className="bg-white rounded-lg border border-gray-200 shadow-sm hover:shadow-md transition flex flex-col h-full">

            {/* IMAGE */}
            <div className="relative h-36 bg-gray-50 flex items-center justify-center p-3">

                {isDealActive && (
                    <span className="absolute top-2 left-2 bg-red-500 text-white text-[10px] px-2 py-[2px] rounded">
                        {discount}% OFF
                    </span>
                )}

                <img
                    src={imageUrl}
                    alt={name}
                    className="w-full h-full object-contain"
                />

                <button
                    onClick={() => setLiked(!liked)}
                    className="absolute top-2 right-2 bg-white p-1.5 rounded-full shadow"
                >
                    {liked ? "❤️" : "🤍"}
                </button>
            </div>

            {/* CONTENT */}
            <div className="p-3 flex flex-col flex-grow">

                {/* BRAND */}
                <p className="text-[11px] text-gray-400 uppercase leading-none">
                    {brand}
                </p>

                {/* NAME */}
                <h3 className="text-sm font-semibold text-gray-900 leading-tight line-clamp-2 min-h-[34px] mt-[2px]">
                    {name}
                </h3>

                {/* PRICE / QUOTE */}
                <div className="min-h-[40px] flex flex-col justify-center mt-[2px]">

                    {isNormal ? (
                        <div className="flex items-center gap-2 flex-wrap">

                            <span className="text-[15px] font-bold text-blue-700">
                                ₹{Math.round(finalPrice).toLocaleString("en-IN")}
                            </span>

                            {isDealActive ? (
                                <>
                                    <span className="text-xs text-gray-400 line-through">
                                        ₹{Math.round(price).toLocaleString("en-IN")}
                                    </span>

                                    <span className="text-[10px] text-green-600">
                                        {discount}% OFF
                                    </span>
                                </>
                            ) : (
                                <span className="text-[10px] text-gray-400">
                                    Best Price
                                </span>
                            )}

                        </div>
                    ) : (
                        <span className="text-orange-600 text-xs font-medium">
                            Request for Quote
                        </span>
                    )}

                </div>

                {/* DELIVERY */}
                <div className="text-[11px] text-gray-500 mt-[2px]">
                    🚚 Delivery 3–5 days
                </div>

                {/* BUTTON */}
                <div className="mt-auto pt-2">

                    {isNormal ? (
                        cart[id] ? (
                            <div className="flex items-center justify-between border rounded-md px-2 py-1 text-sm">
                                <button onClick={() => decreaseQty(id)}>−</button>
                                <span>{cart[id]}</span>
                                <button onClick={() => increaseQty(id)}>+</button>
                            </div>
                        ) : (
                            <button
                                onClick={() => addToCart(id)}
                                className="w-full bg-gradient-to-r from-sky-500 to-blue-600 text-white py-1.5 rounded-md text-sm font-medium"
                            >
                                Add to Cart
                            </button>
                        )
                    ) : (
                        <button
                            onClick={() =>
                                window.location.href = `https://localhost:7030/Home/Enquiry?productId=${id}`
                            }
                            className="w-full bg-orange-500 text-white py-1.5 rounded-md text-sm font-medium"
                        >
                            Request Quote
                        </button>
                    )}

                </div>

            </div>
        </div>
    );
}