import React, { useEffect, useState } from "react";
import API from "../services/api";
import ProductCard from "../components/ProductCard";
import MainBanner from "../components/MainBanner";
import CategoryRow from "../components/CategoryRow";
import { useParams } from "react-router-dom";
import HotDeals from "../components/HotDeals";
import MainLayout from "../layouts/MainLayout";

export default function ProductList() {

    const [products, setProducts] = useState([]);
    const [allProducts, setAllProducts] = useState([]);
    const [cart, setCart] = useState({});

    const { categoryName } = useParams();

    const isCategoryPage =
        categoryName && categoryName.toLowerCase() !== "all";

    // 🔥 Fetch
    useEffect(() => {
        API.get("/api/products")
            .then(res => {
                console.log("RAW:", res.data);

                let data = res.data;

                if (data && data.$values) {
                    data = data.$values;
                }

                if (!Array.isArray(data)) {
                    data = [];
                }

                setAllProducts(data);
            })
            .catch(err => console.error(err));
    }, []);

    // 🎯 Filter
    useEffect(() => {
        if (!isCategoryPage) {
            setProducts(allProducts);
        } else {
            const filtered = allProducts.filter(p =>
                (p.category || p.Category || "")
                    .toLowerCase()
                    .trim() === categoryName.toLowerCase().trim()
            );
            setProducts(filtered);
        }

        window.scrollTo({ top: 0, behavior: "smooth" });

    }, [categoryName, allProducts, isCategoryPage]);

    // 🛒 Cart
    const addToCart = (id) =>
        setCart(prev => ({ ...prev, [id]: 1 }));

    const increaseQty = (id) =>
        setCart(prev => ({
            ...prev,
            [id]: (prev[id] || 1) + 1
        }));

    const decreaseQty = (id) =>
        setCart(prev => {
            const qty = (prev[id] || 1) - 1;
            if (qty <= 0) {
                const next = { ...prev };
                delete next[id];
                return next;
            }
            return { ...prev, [id]: qty };
        });

    // 🔥 Hot Deals
    const hotDeals = allProducts.filter(p =>
        (p.isHotDeal ?? p.IsHotDeal) &&
        (p.discount ?? p.DiscountPercentage ?? 0) > 0
    );

    return (
        <MainLayout>

            <div className="bg-gradient-to-b from-white via-gray-50 to-gray-100 min-h-screen">

                <div className="max-w-7xl mx-auto px-4 py-5">

                    {/* 🔥 HOME PAGE */}
                    {!isCategoryPage && (
                        <>
                            <MainBanner />

                            <div className="sticky top-0 z-30 bg-white/80 backdrop-blur-md pt-3 pb-2">
                                {allProducts.length > 0 ? (
                                    <CategoryRow
                                        activeCategory={categoryName}
                                        products={allProducts}
                                    />
                                ) : (
                                    <p className="text-center text-sm text-gray-400">Loading categories...</p>
                                )}
                            </div>

                            <div className="mt-3">
                                <HotDeals
                                    products={hotDeals}
                                    addToCart={addToCart}
                                />
                            </div>
                        </>
                    )}

                    {/* 🎯 CATEGORY PAGE */}
                    {isCategoryPage && (
                        <div className="sticky top-0 z-30 bg-white/80 backdrop-blur-md pt-3 pb-2">
                            {allProducts.length > 0 ? (
                                <CategoryRow
                                    activeCategory={categoryName}
                                    products={allProducts}
                                />
                            ) : (
                                <p className="text-center text-sm text-gray-400">Loading categories...</p>
                            )}
                        </div>
                    )}

                    {/* PRODUCT SECTION */}
                    <div className="mt-6 mb-4">
                        <h2 className="text-16xl font-bold">
                            {isCategoryPage ? categoryName : "Products For You"}
                        </h2>
                    </div>

                    {/* GRID */}
                    {products.length === 0 ? (
                        <p className="text-center mt-10">No products found</p>
                    ) : (
                        <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
                            {products.map((p, index) => (
                                <ProductCard
                                    key={p.id || index}
                                    p={p}
                                    cart={cart}
                                    addToCart={addToCart}
                                    increaseQty={increaseQty}
                                    decreaseQty={decreaseQty}
                                />
                            ))}
                        </div>
                    )}

                </div>

            </div>

        </MainLayout>
    );
}