import { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import API from "../services/api";

export default function MainHeader() {
    const [user, setUser] = useState(null);
    const [cartCount, setCartCount] = useState(0);
    const [wishlistCount, setWishlistCount] = useState(0);
    const [menuOpen, setMenuOpen] = useState(false);

    const [search, setSearch] = useState("");
    const [suggestions, setSuggestions] = useState([]);

    const navigate = useNavigate();

    useEffect(() => {
        API.get("/api/user")
            .then(res => setUser(res.data))
            .catch(() => setUser(null));

        API.get("/Cart/Count").then(res => setCartCount(res.data));
        API.get("/Wishlist/Count").then(res => setWishlistCount(res.data));
    }, []);

    // 🔍 SEARCH
    useEffect(() => {
        if (search.trim().length < 2) {
            setSuggestions([]);
            return;
        }

        const timer = setTimeout(() => {
            API.get(`/api/products/search?term=${search}`)
                .then(res => setSuggestions(res.data));
        }, 300);

        return () => clearTimeout(timer);
    }, [search]);

    const handleSearch = () => {
        navigate(`/search/${search}`);
        setSuggestions([]);
    };

    const isKycDone = user?.isProfileCompleted;

    return (
        <header className="sticky top-0 z-50 bg-white shadow-md">

            {/* TOP STRIP */}
            <div className="bg-gradient-to-r from-pink-500 to-purple-600 text-white text-xs text-center py-1">
                🚀 Trusted Medical Store
            </div>

            <div className="max-w-7xl mx-auto px-4 flex items-center justify-between h-16">

                {/* LEFT */}
                <div className="flex items-center gap-4">

                    {/* HOME */}
                    <button
                        onClick={() => navigate("/")}
                        className="text-lg font-semibold hover:text-blue-600"
                    >
                        🏠 Home
                    </button>

                    {/* LOGO */}
                    <img src="/images/sunillogo.png" className="h-9" />
                </div>

                {/* 🔍 SEARCH */}
                <div className="flex-1 mx-6 relative hidden md:block">

                    <div className="flex items-center bg-gray-100 rounded-full px-3">
                        <input
                            value={search}
                            onChange={(e) => setSearch(e.target.value)}
                            placeholder="Search products..."
                            className="flex-1 bg-transparent py-2 outline-none"
                        />

                        <button onClick={handleSearch}>
                            🔍
                        </button>
                    </div>

                    {/* Suggestions */}
                    {suggestions.length > 0 && (
                        <div className="absolute top-12 w-full bg-white shadow-xl rounded-lg z-50">

                            {suggestions.map(item => (
                                <div
                                    key={item.id}
                                    onClick={() => navigate(`/product/${item.id}`)}
                                    className="p-3 flex gap-3 hover:bg-gray-100 cursor-pointer"
                                >
                                    <img src={item.imageUrl} className="w-10 h-10" />
                                    <div>
                                        <p>{item.name}</p>
                                        <p className="text-xs text-gray-500">{item.brand}</p>
                                    </div>
                                </div>
                            ))}

                        </div>
                    )}

                </div>

                {/* RIGHT MENU */}
                <div className="flex items-center gap-6">

                    {/* KYC */}
                    {user && (
                        <button
                            onClick={() => navigate(isKycDone ? "/kyc/view" : "/kyc/register")}
                            className={`text-sm px-3 py-1 rounded-full ${isKycDone
                                    ? "bg-green-100 text-green-600"
                                    : "bg-orange-100 text-orange-600"
                                }`}
                        >
                            {isKycDone ? "KYC ✓" : "KYC"}
                        </button>
                    )}

                    {/* WISHLIST */}
                    <Link to="/wishlist">❤️ {wishlistCount}</Link>

                    {/* CART */}
                    <Link to="/cart">🛒 {cartCount}</Link>

                    {/* PROFILE */}
                    {user ? (
                        <div className="relative">
                            <button onClick={() => setMenuOpen(!menuOpen)}>
                                👤 {user.name}
                            </button>

                            {menuOpen && (
                                <div className="absolute right-0 bg-white shadow-lg rounded p-3">
                                    <button onClick={() => navigate("/profile")}>Profile</button>
                                    <button onClick={() => navigate("/orders")}>Orders</button>
                                </div>
                            )}
                        </div>
                    ) : (
                        <button onClick={() => navigate("/login")}>Login</button>
                    )}

                </div>
            </div>
        </header>
    );
}